styles.css:
.has-display-xl-font-size { font-weight: 600; line-height: 0.92; letter-spacing: -0.03em; }
.has-display-font-size { font-weight: 600; line-height: 0.95; letter-spacing: -0.03em; }
.has-h1-font-size { font-weight: 600; line-height: 1; letter-spacing: -0.02em; }
.has-h2-font-size { font-weight: 600; line-height: 1.05; letter-spacing: -0.02em; }
.has-h3-font-size { font-weight: 600; line-height: 1.15; letter-spacing: 0em; }
.has-h4-font-size { font-weight: 600; line-height: 1.2; letter-spacing: 0em; }
.has-lead-font-size { font-weight: 400; line-height: 1.4; letter-spacing: 0em; }
.has-body-l-font-size { font-weight: 400; line-height: 1.5; letter-spacing: 0em; }
.has-body-font-size { font-weight: 400; line-height: 1.55; letter-spacing: 0em; }
.has-small-font-size { font-weight: 400; line-height: 1.45; letter-spacing: 0em; }
.has-label-font-size { font-weight: 600; line-height: 1.2; letter-spacing: 0em; }
.has-button-font-size { font-weight: 600; line-height: 1.2; letter-spacing: 0em; }
/* CREATE V2.1: local wrapping; do not clip content. */
.diged-create-v2 .wp-block-column { min-width: 0; }
.diged-create-v2 :is(h1, h2, h3, p, .wp-block-button__link) { overflow-wrap: anywhere; }
/* Native Columns switches at 782px; stack earlier to protect editorial columns. */
@media (max-width: 1024px) {
  .diged-create-v2 > section { padding-top: var(--wp--preset--spacing--80) !important; padding-bottom: var(--wp--preset--spacing--80) !important; }
  .diged-create-v2 > section:first-child, .diged-create-v2 > #conversar { padding-top: var(--wp--preset--spacing--90) !important; padding-bottom: var(--wp--preset--spacing--90) !important; }
  .diged-create-v2 .wp-block-columns { flex-wrap: wrap !important; gap: var(--wp--preset--spacing--60); }
  .diged-create-v2 .wp-block-columns > .wp-block-column { flex-basis: 100% !important; }
}
@media (max-width: 781px) {
  .diged-create-v2 > #conversar { padding-top: var(--wp--preset--spacing--80) !important; padding-bottom: var(--wp--preset--spacing--80) !important; }
}

/* Fix the saved V2 instance that still carries has-brand-color on the process H2. */
.diged-create-v2 #como-funciona h2 { color: var(--wp--preset--color--black) !important; }
@media (max-width: 781px) {
  /* Headings break at spaces only; override the earlier emergency wrap rule. */
  .diged-create-v2 :is(h1, h2, h3) { overflow-wrap: normal; word-break: normal; hyphens: none; }
  .diged-create-v2 h1.has-display-xl-font-size,
  .diged-create-v2 > .has-black-background-color .has-display-font-size,
  .diged-create-v2 > #conversar .has-display-font-size { font-size: clamp(2.5rem, 1.35714286rem + 5.71428571vw, 2.75rem) !important; }
  /* Delivery items remain stacked, with 48px instead of 32px between them. */
  .diged-create-v2 > .has-brand-background-color .wp-block-columns { row-gap: var(--wp--preset--spacing--70); }
  /* Keep each divider close to its step; separate complete steps by 48px. */
  .diged-create-v2 #como-funciona .wp-block-separator { margin-block-start: var(--wp--preset--spacing--70); margin-block-end: 0; }
  .diged-create-v2 #como-funciona .wp-block-separator + .wp-block-columns { margin-block-start: var(--wp--preset--spacing--40); row-gap: var(--wp--preset--spacing--40); }
}

/* Header V2 Shift: native Navigation owns opening, focus and keyboard behavior. */
.diged-header { padding: var(--wp--preset--spacing--60) var(--wp--preset--spacing--40); }
.diged-header__row { gap: var(--wp--preset--spacing--60); }
.diged-header .diged-header__brand { flex: 0 0 auto; margin: 0; }
.diged-header .diged-header__brand img { display: block; width: 200px; max-width: 100%; height: auto; }
.diged-header .diged-header__brand a { display: block; }
.diged-header .wp-block-navigation { font-weight: 500; }
.diged-header .wp-block-navigation-item__content { display: flex; align-items: center; min-height: 44px; box-sizing: border-box; padding: var(--wp--preset--spacing--30); color: var(--wp--preset--color--black); text-decoration: none; transition: color 180ms ease-out; }
.diged-header .wp-block-navigation-item__label { display: inline-block; transition: transform 180ms ease-out; }
.diged-header .diged-header__contact > .wp-block-navigation-item__content { font-weight: 600; }
.diged-header .diged-header__arrow { display: inline-block; margin-inline-start: 0.25em; transition: transform 180ms ease-out; }
.diged-header .wp-block-navigation-item__content:is(:hover, :focus-visible, :active, [aria-current="page"]), .diged-header .current-menu-item > .wp-block-navigation-item__content { color: var(--wp--preset--color--brand); }
.diged-header .wp-block-navigation-item__content:is(:hover, :focus-visible) .wp-block-navigation-item__label { transform: translateY(-2px); }
.diged-header .wp-block-navigation-item__content:is(:hover, :focus-visible) .diged-header__arrow { transform: translate(2px, -2px); }
.diged-header :is(a, button):focus-visible { outline: 2px solid var(--wp--preset--color--black); outline-offset: 4px; }
.diged-header :is(.wp-block-navigation__responsive-container-open, .wp-block-navigation__responsive-container-close) { min-width: 44px; min-height: 44px; align-items: center; justify-content: center; }
@media (max-width: 1024px) {
  .diged-header { padding-top: var(--wp--preset--spacing--50); padding-bottom: var(--wp--preset--spacing--50); }
  .diged-header .diged-header__brand img { width: 180px; }
  .diged-header .wp-block-navigation__responsive-container-open { display: flex !important; }
  .diged-header .wp-block-navigation__responsive-container:not(.is-menu-open) { display: none !important; }
  .diged-header .wp-block-navigation__responsive-container.is-menu-open { position: fixed; inset: 0; box-sizing: border-box; min-height: 100dvh; overflow-y: auto; padding: var(--wp--preset--spacing--60); color: var(--wp--preset--color--white); background: var(--wp--preset--color--black); }
  .diged-header .is-menu-open .wp-block-navigation__responsive-container-close { display: flex; color: var(--wp--preset--color--white); }
  .diged-header .is-menu-open .wp-block-navigation__responsive-container-content { align-items: stretch; padding-top: var(--wp--preset--spacing--80); }
  .diged-header .is-menu-open .wp-block-navigation__container { width: 100%; min-height: calc(100dvh - 8rem); box-sizing: border-box; padding-bottom: var(--wp--preset--spacing--60); flex-direction: column; align-items: stretch; gap: var(--wp--preset--spacing--50); }
  .diged-header .is-menu-open .wp-block-navigation-item__content { color: var(--wp--preset--color--white); font-size: clamp(2rem, 1.5rem + 2vw, 3rem); line-height: 1.15; font-weight: 600; }
  .diged-header .is-menu-open .wp-block-navigation-item__content:is(:hover, :focus-visible, :active, [aria-current="page"]), .diged-header .is-menu-open .current-menu-item > .wp-block-navigation-item__content { color: var(--wp--preset--color--brand); }
  .diged-header .is-menu-open .diged-header__contact { margin-top: auto; padding-top: var(--wp--preset--spacing--50); border-top: 1px solid var(--wp--preset--color--graphite); }
  .diged-header .is-menu-open .diged-header__contact > .wp-block-navigation-item__content { font-size: var(--wp--preset--font-size--button); color: var(--wp--preset--color--white); }
  .diged-header .is-menu-open .diged-header__arrow { color: var(--wp--preset--color--brand); }
  .diged-header .is-menu-open :is(a, button):focus-visible { outline-color: var(--wp--preset--color--white); }
}
@media (prefers-reduced-motion: reduce) {
  .diged-header .wp-block-navigation-item__content, .diged-header .wp-block-navigation-item__label, .diged-header .diged-header__arrow { transition: none; transform: none !important; }
}
/* Specific Header/CREATE relationship: no change to the other sections or H1. */
.wp-site-blocks > header:has(.diged-header) + main .diged-create-v2 > section:first-child { padding-top: var(--wp--preset--spacing--80) !important; }
